import{_ as n,C as a,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Open the register","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/sessions/open-register.md","filePath":"master/sales/point-of-sale/sessions/open-register.md","lastUpdated":1793074831000}'),l={name:"master/sales/point-of-sale/sessions/open-register.md"};function h(g,e,p,c,d,u){const s=a("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="open-the-register" tabindex="-1">Open the register <a class="header-anchor" href="#open-the-register" aria-label="Permalink to &quot;Open the register&quot;">​</a></h1><p>Opening the register starts a new session and tells the system how much cash is in the drawer. You do this at the start of every shift or trading day. Until the register is open, you cannot sell.</p><blockquote><p><strong>In simple words:</strong> Open the register, confirm the cash in the drawer, and start selling.</p></blockquote><p>You can open a register from the back office <strong>Dashboard</strong> or from the terminal&#39;s <strong>Registers</strong> page. Both lead to the same <strong>Opening Control</strong> window.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>The register must be active and set up with its journals, payment methods and accounts. If something is missing, Aureus shows a message when you try to open. See <a href="./../get-started/set-up-a-register.html">Set up a register</a>.</p><h2 id="open-from-the-dashboard" tabindex="-1">Open from the Dashboard <a class="header-anchor" href="#open-from-the-dashboard" aria-label="Permalink to &quot;Open from the Dashboard&quot;">​</a></h2><ol><li>Go to <code>Point of Sale → Dashboard</code>.</li><li>Find the card of your register, for example <strong>TechNest Electronics</strong>.</li><li>Click <strong>Open Register</strong>. The terminal opens.</li></ol>',8)),o(s,{src:"/images1/pos/dashboard_register_cards.png",alt:"Dashboard register cards for Spice Route Kitchen & Bar and TechNest Electronics, each with a Continue Selling button"}),e[1]||(e[1]=t('<p>A register that already has a live session shows <strong>Continue Selling</strong> instead. Click it to go back to the same session.</p><h2 id="open-from-the-terminal" tabindex="-1">Open from the terminal <a class="header-anchor" href="#open-from-the-terminal" aria-label="Permalink to &quot;Open from the terminal&quot;">​</a></h2><ol><li>Open the terminal at <code>/pos/registers</code>. This page lists every register.</li><li>Click <strong>Open register</strong> under the register you want. A register that is already open shows <strong>Resume</strong>.</li></ol>',3)),o(s,{src:"/images1/pos/terminal_registers.png",alt:"Terminal Registers page with Spice Route Kitchen & Bar and TechNest Electronics, each showing its session status and a Resume button"}),e[2]||(e[2]=t('<p>Each card shows the register name, its short code and its status, such as <strong>Closed</strong> or <strong>Open by ERP Admin</strong>.</p><h2 id="the-opening-control-window" tabindex="-1">The Opening Control window <a class="header-anchor" href="#the-opening-control-window" aria-label="Permalink to &quot;The Opening Control window&quot;">​</a></h2><p>After you open, the <strong>Opening Control</strong> window appears over the till.</p><ul><li><strong><em>Opening cash:</em></strong> The cash you put in the drawer. The hint under the field shows the closing balance of the last session, so you can compare. Type the amount.</li><li><strong><em>Opening note:</em></strong> An optional message for the closing check, such as who prepared the drawer.</li></ul><ol start="3"><li>Click the card icon next to <strong>Opening cash</strong> if you want to count by coin and note.</li></ol>',5)),o(s,{src:"/images1/pos/opening_control_window.png",alt:"Opening Control window with Previous session closing balance, Opening cash 1750, an opening note and the Open Register button"}),e[3]||(e[3]=t('<h3 id="count-coins-and-notes" tabindex="-1">Count coins and notes <a class="header-anchor" href="#count-coins-and-notes" aria-label="Permalink to &quot;Count coins and notes&quot;">​</a></h3><p>The <strong>Coins/Notes</strong> window lists every denomination with a counter. Click <strong>+</strong> or type the number of each coin or note. The <strong>Total</strong> at the bottom updates as you count. Click <strong>Confirm</strong> and the total fills <strong>Opening cash</strong>.</p>',2)),o(s,{src:"/images1/pos/coins_notes_counter.png",alt:"Coins/Notes window with 5 notes of 200, 4 of 100, 5 of 50 and 5 of 20 and a total of 1,750"}),e[4]||(e[4]=t('<p>The denominations come from your list of coins and bills. See <a href="./../payments-setup/coins-and-bills.html">Coins and bills</a>.</p><ol start="4"><li>Click <strong>Open Register</strong>.</li></ol><p>The till opens with an empty order and the session status becomes <strong>In Progress</strong>.</p><p><strong>Example:</strong> TechNest counts 5 notes of 200, 4 of 100, 5 of 50 and 5 of 20. The total is 1,750. The cashier types the note &quot;Float prepared by ERP Admin&quot; and clicks <strong>Open Register</strong>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Open Register:</strong> Confirms the opening cash and moves the session from <strong>Opening Control</strong> to <strong>In Progress</strong>.</li><li><strong>Resume:</strong> Returns to a session that is already in progress.</li><li><strong>Discard session:</strong> Removes a session that has no orders and no cash movements. Use it if you opened by mistake.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If a session is stuck in <strong>Opening Control</strong>, a manager can click <strong>Open Session</strong> on it in <code>Point of Sale → Orders → Sessions</code>. See <a href="./">Register sessions</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Count the drawer honestly. The opening cash is the starting point for the expected balance at closing.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../selling/terminal-overview.html">Terminal tour</a></li><li><a href="./cash-in-and-out.html">Cash in and out</a></li><li><a href="./close-session.html">Close a session</a></li></ul>',10))])}const _=n(l,[["render",h]]);export{f as __pageData,_ as default};
